The trick is to narrow the `any` with `isinstance` guards before you flow the value into a declared type. Here's the parse helper:

```jac
import json;

def parse(text: str) -> any {
    return json.loads(text);
}

obj Task { has title: str = ""; }
```

The `parse` return is intentionally `any` so it accepts anything json produces.

Guard twice: first confirm it's a `dict`, then confirm the field is a `str` before passing it to `Task`. After each `isinstance`, the checker narrows the type:

```jac
import json;

def parse(text: str) -> any {
    return json.loads(text);
}

obj Task { has title: str = ""; }

with entry {
    # Inferred destination -- `raw` becomes `any`, no error.
    raw = parse('{"title": "ship"}');

    # Narrow before flowing into a declared type.
    if isinstance(raw, dict) {
        title = raw.get("title", "");
        if isinstance(title, str) {
            t = Task(title=title);
            print(t.title);
        }
    }
}
```

