Wrapped the decode in a try/except so a malformed payload yields None instead of propagating. The entry block runs several cases including the bad-JSON one:

```jac
"""Scan text for the first 'BENCH_JSON ' line and return the decoded JSON after it, or None (on no match or a decode error)."""

import json;

def _parse_bench_json(text: str) -> any {
    marker = "BENCH_JSON ";
    for line in text.splitlines() {
        s = line.strip();
        if s.startswith(marker) {
            try {
                return json.loads(s[len(marker):]);
            } except Exception as e {
                return None;
            }
        }
    }
    return None;
}

with entry {
