        "BENCH_JSON [1, 2, 3]",
        "no marker here\nstill nothing",
        "   BENCH_JSON {bad json}",
        "BENCH_JSON 42"
    ];
    for c in cases {
        r = _parse_bench_json(c);
        print(str(r));
    }
}
