Added a `build()` that assembles the query string and respects the optional limit:

```jac
obj QueryBuilder {
    has table: str = "",
        limit_val: int = -1;

    def from_table(table: str) -> Self {
        self.table = table;
        return self;
    }

    def limit(n: int) -> Self {
        self.limit_val = n;
        return self;
    }

    def build() -> str {
        query = f"SELECT * FROM {self.table}";
        if self.limit_val >= 0 {
            query += f" LIMIT {self.limit_val}";
        }
        return query;
    }
}

with entry {
    q = QueryBuilder().from_table("users").limit(10).build();
    print(q);
}
