Task manager with two walkers, `CheckReady` and `MarkComplete`. Move ability bodies into impl blocks so the walkers are just declarations at the top. Code:

```jac
node Task { has title: str; has status: str = "pending"; has priority: int = 1; }
edge DependsOn {}

walker CheckReady {
    has ready_tasks: list = [];
    can start with Root entry { visit [-->]; }
    can check with Task entry {
        if here.status != "pending" { return; }
        dependencies = [here ->:DependsOn:->];
        all_done = True;
        for dep in dependencies {
            if dep.status != "complete" { all_done = False; break; }
        }
        if all_done { self.ready_tasks.append(here.title); }
    }
}

walker MarkComplete {
    has task_title: str;
    can start with Root entry { visit [-->]; }
    can mark with Task entry {
