A small but real notes app that doubles as the CEF desktop smoke test. It
exercises jac-desktop infrastructure end-to-end:
  - window.__JAC_DESKTOP__ / window.__JAC_BROKER__ bootstrap injection
  - loopback broker routes at /__jac/* (health + session)
  - localStorage on a stable loopback origin (notes persist across restarts)

The bootstrap/broker diagnostics live behind a collapsible "Diagnostics"
drawer in the footer so they keep working as a smoke probe without dominating
the UI.
"""
cl {
    def:pub app -> JsxElement {
        has notes: list = [],
            activeId: str = "",
            query: str = "",
            diagnosticsOpen: bool = False,
            desktopFlag: any = None,
            brokerPrefix: str = "",
            origin: str = "",
            health: any = None,
            session: any = None,
            brokerError: str = "",
            tick: int = 0;

        # ---- persistence -------------------------------------------------
        STORAGE_KEY = "notes_app_notes_v2";

        def loadNotes -> any {
            raw = localStorage.getItem(STORAGE_KEY);
            if not raw {
                return [];
            }
            try {
                return JSON.parse(raw);
            } except Exception { }
            return [];
        }

        def persist {
            localStorage.setItem(STORAGE_KEY, JSON.stringify(notes));
        }

        # ---- note operations --------------------------------------------
        def newNote {
            id = "n_" + str(Date.now()) + "_" + str(tick);
            note = {
                "id": id,
                "title": "Untitled note",
                "body": "",
                "updatedAt": Date.now()
            };
            notes = [note] + notes;
            activeId = id;
            persist();
        }

        def selectNote(id: str) {
            activeId = id;
        }

        def deleteNote(id: str) {
            notes = [
                n
                for n in notes
                if n["id"] != id
            ];
            if activeId == id {
                activeId = notes[0]["id"] if len(notes) > 0 else "";
            }
            persist();
        }

        def duplicateNote(id: str) {
            src: any = None;
            for n in notes {
                if n["id"] == id {
                    src = n;
                }
            }
            if src is None {
                return;
            }
            newId = "n_" + str(Date.now()) + "_" + str(tick);
            copy = {
                "id": newId,
                "title": str(src["title"]) + " (copy)",
                "body": src["body"],
                "updatedAt": Date.now()
            };
            notes = [copy] + notes;
            activeId = newId;
            persist();
        }

        def patchActive(title: str, body: str) {
            if activeId == "" {
                return;
            }
            now = Date.now();
            rebuilt = [];
            for n in notes {
                if n["id"] == activeId {
                    rebuilt.append(
                        {"id": n["id"], "title": title, "body": body, "updatedAt": now}
                    );
                } else {
                    rebuilt.append(n);
                }
            }
            notes = rebuilt;
            persist();
        }

        # ---- derived helpers --------------------------------------------
        def activeNote -> any {
            if activeId == "" {
                return None;
            }
            for n in notes {
                if n["id"] == activeId {
                    return n;
                }
            }
            return None;
        }

        def filteredNotes -> list {
            q = query.strip().lower();
            if q == "" {
                return notes;
            }
            return [
                n
                for n in notes
                if q in str(n["title"]).lower() or q in str(n["body"]).lower()
            ];
        }

        def preview(body: str) -> str {
            flat = str(body).replace("\n", " ").strip();
            if len(flat) > 70 {
                return flat[:70] + "...";
            }
            return flat;
        }

        def relTime(ts: any) -> str {
            try {
                ms = int(ts);
            } except Exception {
                return "";
            }
            diff = Date.now() - ms;
            s = int(diff / 1000);
            if s < 60 {
                return "just now";
            }
            m = int(s / 60);
            if m < 60 {
                return str(m) + "m ago";
            }
            h = int(m / 60);
            if h < 24 {
                return str(h) + "h ago";
            }
            d = int(h / 24);
            if d < 7 {
                return str(d) + "d ago";
            }
            return Date(ms).toLocaleDateString();
