My CLI entry point that parses a `--benchmark` flag. Anything you'd change?

```jac
import sys;

glob game = Game();

with entry {
    _benchmark_mode: int = 0;
    _args = sys.argv;
    for i in range(1, len(_args)) {
        arg = _args[i];
        if arg == "--benchmark" or arg == "-b" {
            _benchmark_mode = 10;
