Then model the counter as an object with its own state and methods, and use a small factory lambda to spin them up:

```jac
obj Counter {
    has count: int;
    def inc -> None { self.count += 1; }
    def get -> int  { return self.count; }
}

glob make_counter = lambda start: int -> Counter : Counter(count=start);

