            report {"deleted": self.task_id};
            disengage;
        }
    }
}

# New feature: clear all completed tasks in a single traversal.
walker:priv ClearCompletedTasks {
    has removed: int = 0,
        reports: list[dict[str, int]] = [];
    can search with Root entry { visit [-->]; }
    can prune with Task entry {
        if here.done {
            self.removed += 1;
            del here;
        }
    }
    can finish with Root exit { report {"removed": self.removed}; }
}

walker:priv GenerateShoppingList {
    has meal_description: str, reports: list[list[ShoppingItem]] = [];
    can generate with Root entry {
        visit [-->];
        ingredients = generate_shopping_list(self.meal_description);
        for ing in ingredients {
            here ++> ShoppingItem(
                name=ing.name, quantity=ing.quantity,
                unit=str(ing.unit).split(".")[-1].lower(),
                cost=ing.cost, carby=ing.carby
            );
        }
        report [here-->][?:ShoppingItem];
    }
    can clear_old with ShoppingItem entry { del here; }
}

walker:priv GetShoppingList {
    has items: list[ShoppingItem] = [], reports: list[list[ShoppingItem]] = [];
    can collect with Root entry { visit [-->]; }
    can gather with ShoppingItem entry { self.items.append(here); }
    can done with Root exit { report self.items; }
}

walker:priv ClearShoppingList {
    can collect with Root entry { visit [-->]; }
    can clear with ShoppingItem entry {
        del here;
        report {"cleared": True};
    }
}
