My auth context reports everyone as authenticated, even logged-out visitors, so gated content unlocks for anybody. Here's the provider:

```jac
cl import from "@jac/runtime" { jacIsLoggedIn, jacLogin, jacLogout }

cl {
    import from react { createContext, useContext }

    glob AuthContext = createContext(None);

    # Auth Provider component -- `children` holds the nested JSX
    def:pub AuthProvider(children: any = None) -> JsxElement {
        has user: any = None;
        has loading: bool = True;

        can with entry {
            # Check auth status on mount
            if jacIsLoggedIn() {
                # Optionally fetch user data from backend
                user = {"authenticated": True};
            }
            loading = False;
        }

        async def login(username: str, password: str) -> bool {
            success = await jacLogin(username, password);
            if success {
                user = {"authenticated": True};
            }
            return success;
        }

        def logout() -> None {
            jacLogout();
            user = None;
        }

        value = {
            "user": user,
            "loading": loading,
            "isAuthenticated": user == None,
            "login": login,
            "logout": logout
        };

        return <AuthContext.Provider value={value}>
            {children}
        </AuthContext.Provider>;
    }

    def useAuth() -> dict {
        return useContext(AuthContext);
    }
}
```

Why is `isAuthenticated` always coming back true for logged-out users?

Then it's not timing -- look at how `isAuthenticated` is computed. You wrote `user == None`, which is `True` exactly when there is *no* user. That's inverted. It should be true when a user *exists*:

```jac
cl import from "@jac/runtime" { jacIsLoggedIn, jacLogin, jacLogout }

cl {
    import from react { createContext, useContext }

    glob AuthContext = createContext(None);

    # Auth Provider component -- `children` holds the nested JSX
    def:pub AuthProvider(children: any = None) -> JsxElement {
        has user: any = None;
        has loading: bool = True;

        can with entry {
            # Check auth status on mount
            if jacIsLoggedIn() {
                # Optionally fetch user data from backend
                user = {"authenticated": True};
            }
            loading = False;
        }

        async def login(username: str, password: str) -> bool {
            success = await jacLogin(username, password);
            if success {
                user = {"authenticated": True};
            }
            return success;
        }

        def logout() -> None {
