Lift the key-map dictionary out of `_keymap` into a module-level constant so it isn't rebuilt on every call.

```jac
def _keymap(code: str) -> int {
    m = {
        "KeyW": 87, "KeyA": 65, "KeyS": 83, "KeyD": 68, "Space": 32,
        "Tab": 258, "ArrowRight": 262, "ArrowLeft": 263, "ArrowDown": 264, "ArrowUp": 265
    };
    return m.get(code, 0);
}
```

Good call — rebuilding the dict per call is wasteful. Lifted to a glob:

```jac
glob _KEYMAP: dict = {
    "KeyW": 87, "KeyA": 65, "KeyS": 83, "KeyD": 68, "Space": 32,
    "Tab": 258, "ArrowRight": 262, "ArrowLeft": 263, "ArrowDown": 264, "ArrowUp": 265
};

def _keymap(code: str) -> int {
    return _KEYMAP.get(code, 0);
}
```

That's because `_KEYMAP` is a `dict` with unannotated value types, so `.get(...)` is inferred as `any`, which doesn't satisfy the `-> int` return. Wrap it in `int(...)` to pin the type:

```jac
"""_keymap: lookup table lifted to a module-level glob constant."""

glob _KEYMAP: dict = {
    "KeyW": 87,
    "KeyA": 65,
    "KeyS": 83,
    "KeyD": 68,
    "Space": 32,
    "Tab": 258,
    "ArrowRight": 262,
    "ArrowLeft": 263,
    "ArrowDown": 264,
    "ArrowUp": 265
};

def _keymap(code: str) -> int {
    return int(_KEYMAP.get(code, 0));
}

with entry {
    codes = ["KeyW", "ArrowUp", "Space", "Nope"];
    parts = [];
    for code in codes {
        parts.append(str(_keymap(code)));
    }
    print(" ".join(parts));
}
```

