Yes -- giving `Shape.area` a concrete `impl` returning `0.0` makes the base non-abstract and gives subclasses a sensible fallback to override:

```jac
import math;

obj Shape {
    has name: str;
    def area -> float;
}

obj Circle(Shape) {
    has radius: float;
    override def area -> float;
}

impl Shape.area -> float {
    return 0.0;
}

impl Circle.area -> float {
    return math.pi * self.radius * self.radius;
}

with entry {
