King move generation. I build the 8 neighbor squares with a comprehension, then filter. Thoughts?

```jac
impl King.raw_moves(board: Board) -> list[Move] {
    moves: list[Move] = [];
    row = self.row();
    col = self.col();

    adjacent: list[tuple[int, int]] = [
        (row + dr, col + dc)
        for dr in [-1, 0, 1]
        for dc in [-1, 0, 1]
        if not (dr == 0 and dc == 0)
    ];

    for pos in adjacent {
        (r, c) = pos;
        if board.valid_pos(r, c) {
            target: Piece | None = board.at(r, c);
            if target is None or target.color != self.color {
                moves.append(Move(from_pos=self.pos, to_pos=pos));
            }
        }
    }
    return moves;
}
```

Here -- the intermediate `adjacent` list is gone; a single `dr`/`dc` double loop forms each neighbor, skips the center with `continue`, and validates on the spot. I put it on a self-contained `Piece`/`Board`/`Move` so it type-checks.

```jac
"""King single-step move generation."""

enum Color { WHITE, BLACK }

obj Move {
    has from_pos: tuple[int, int],
        to_pos: tuple[int, int];
}

obj Board {
    has squares: list[list[Piece | None]] = [];
    def valid_pos(r: int, c: int) -> bool { return 0 <= r < 8 and 0 <= c < 8; }
    def at(r: int, c: int) -> Piece | None { return self.squares[r][c]; }
}

obj Piece {
    has color: Color,
        pos: tuple[int, int];

    def row() -> int { return self.pos[0]; }
    def col() -> int { return self.pos[1]; }

    def raw_moves(board: Board) -> list[Move] {
        moves: list[Move] = [];
        row = self.row();
        col = self.col();
        for dr in [-1, 0, 1] {
            for dc in [-1, 0, 1] {
                if dr == 0 and dc == 0 {
                    continue;
                }
                r = row + dr;
                c = col + dc;
                if board.valid_pos(r, c) {
                    target: Piece | None = board.at(r, c);
                    if target is None or target.color != self.color {
                        moves.append(Move(from_pos=self.pos, to_pos=(r, c)));
                    }
                }
            }
        }
        return moves;
    }
}
```

Same eight candidate squares, one traversal, no throwaway list.

